{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.ras_sales_data as WITH inventory as ( select case when i.brand IN (\"RBPL- MOODY\",\"MOODY\") THEN \"MOODY\" ELSE \"RAS\" END as Brand_name , i.sku , i.product_name from `MAPLEMONK.ras_inventory_fact_items` i ), sku_master as ( select sm.sku , sm.brand from `MAPLEMONK.ras_sku_master` sm ) select coalesce(i.Brand_name, case when sm.brand in (\"Moody Store\",\"Moody\",\"Moody Website\",\"B26779\") then \"MOODY\" else (case when sm.brand in (\"RAS LUXURY OILS\",\"RAS Luxury Oils India\",\"RAS Luxury Skincare\",\"RAS Luxury Oils\",\"RBPL - RAS\",\"RAS\",\"24KGOLDYOUDUO\",\"B12759\") then \"RAS\" else (case when sm.brand in(\"RBPL - RAS\") then \"RAS\" else \"MOODY\" end) end) end ) Brand_name , case when s.marketplace in (\"SHOPIFY\",\"SHOPIFYMARKETPLACE\",\"SHOPIFY2\",\"SHOPIFY14\",\"SHOPIFY13\") then \"D2C\" else (case when s.marketplace in (\"CRED-API2\",\"CRED-API\") then \"CRED\" else (case when s.marketplace in (\"FLIPKART\",\"AMAZON.IN\",\"AMAZON_FBA\",\"TATA CLIQ\",\"MYNTRA PPMP\",\"FIRSTCRY\") THEN \"MARKETPLACE\" else (case when s.marketplace in (\"B2B\",\"PRPDUCTION ORDER\",\"DEKIT ORDER\",\"ONEGREEN\",\"PRODUCTION ORDER\") then \"B2B\" else \"OFFLINE\" end ) end ) end ) end as Marketplace_Final , s.* from `MAPLEMONK.ras_sales_consolidated` s left join inventory i on s.sku=i.sku and s.product_name = i.product_name left join sku_master sm on sm.sku = s.sku; create or replace table maplemonk.ras_po_tracker as WITH grn_details as ( select g._id , g.grnId , cast(g.updated_at as timestamp) as grn_updated_date , g.po , g.invoice_id , cast(json_extract_scalar(skus,\'$.productName\') as string) as product_name , cast(json_extract_scalar(skus,\'$.taxPerItem\') as float64) as tax_per_item , cast(json_extract_scalar(skus,\'$.OriginalOrderedQuantity\') as int64) as original_order_quantity ,cast(json_extract_scalar(skus,\'$.totalReturnQuantity\') as int64) as total_returned_quantity , cast(json_extract_scalar(skus,\'$.unitTotal\') as float64) as total_units , cast(json_extract_scalar(skus,\'$.basePrice\') as float64) as base_price , cast(json_extract_scalar(skus,\'$.mrp\') as float64) as mrp , cast(json_extract_scalar(skus,\'$.taxRate\') as float64) as tax_rate , cast(json_extract_scalar(skus,\'$.netAmount\') as float64) as net_Amount , cast(json_extract_scalar(skus,\'$.batchCode\') as string) as batchCode from ( select * , cast(cast(po_number as int64) as string) as po , ROW_NUMBER() OVER (PARTITION BY cast(cast(po_number as int64) as string) ORDER BY updated_at DESC) as rw from `MAPLEMONK.edgistify_get_grn_details` ) g left join unnest(g.skus) as skus where rw = 1 ), po_details as ( select p.isActive , p.po_number , case when p.orderStatus in (\"PUT_AWAY\") then \"PUT AWAY\" else (case when p.orderStatus in (\"GRN_QC\") then \"GRN QC\" else (case when p.orderStatus in (\"PO_SENT\") then \"PO SENT\" else (case when p.orderStatus IN (\"PO_RECEIVED\") then \"PO RECEIVED\" else (case when p.orderStatus in (\"APPROVAL_PENDING\") then \"APPROVAL PENDING\" else p.orderStatus end)end)end)end)end AS orderStatus , safe_cast(p.poCreatedOn as timestamp) as pocreatedon , p.vendor_name , p.warehouse_name , p.shipping_partner , p.poReferenceNumber , p.orderStatusReadable , p.estimated_delivery_date from ( select * , ROW_NUMBER() OVER (PARTITION BY po_number order by pocreatedon desc) as rw from `MAPLEMONK.edgistify_get_po_list` ) p where rw = 1 ) select po.isActive , po.po_number , po.orderStatus , po.poCreatedOn , po.estimated_delivery_date , po.vendor_name , po.warehouse_name , po.shipping_partner , po.poReferenceNumber , po.orderStatusReadable , g.grn_updated_date , g.grnId , g.product_name , g.original_order_quantity , g.total_returned_quantity , g.total_units , g.invoice_id , g.batchCode , g.mrp , g.tax_rate , g.tax_per_item , g.net_Amount from po_details po left join grn_details g on g.po = po.po_number; create or replace table `MAPLEMONK.ras_sell_through_report` as with month_start_and_end as ( select replace(replace(sku, \"`\", \"\"),\"\'\",\"\") as sku , last_day(date(report_generated_date),month) as month , min(Report_generated_date) as opening_date , max(Report_generated_date) as closing_date from `MAPLEMONK.Easyecom_inventory_snapshot` where report_generated_date is not null group by sku, month ), sku_latest as ( select sku,current_inventory from ( select replace(replace(sku, \"`\", \"\"),\"\'\",\"\")as sku , Available_Quantity as current_inventory , row_number () over (partition by replace(replace(sku, \"`\", \"\"),\"\'\",\"\") order by report_generated_date desc) rw from `MAPLEMONK.Easyecom_inventory_snapshot` where report_generated_date is not null ) where rw = 1 ), sales_data as ( select sku , last_day(date(order_date),month) as order_month , count(*) as total_orders_in_month , sum(return_flag) as total_returns_in_month from `MAPLEMONK.ras_sales_data` group by sku, order_month ), inventory_details as ( select replace(replace(i.sku, \"`\", \"\"),\"\'\",\"\") as sku_code , available_quantity , report_generated_date , last_day(date(i.report_generated_date),month) as month from `MAPLEMONK.Easyecom_inventory_snapshot` i ), grn as ( select last_day(date(safe_cast(g.grncompletedat as timestamp)),month) as grn_completed_month , safe_cast(json_extract_scalar(skus,\'$.skuId\') as string) as sku , sum(cast(json_extract_scalar(skus,\'$.OriginalOrderedQuantity\') as int64)) as order_quantity_of_month from ( select * , ROW_NUMBER() OVER (PARTITION BY cast(cast(po_number as int64) as string) ORDER BY updated_at DESC) as rw from `MAPLEMONK.edgistify_get_grn_details` ) g left join unnest(g.skus) as skus where rw = 1 and grnCreatedOn is not null and poStatus <> \"CANCELLED\" group by 1,2 ) select sd.sku , safe_cast(sd.order_month as date) as month , safe_cast(s.current_inventory as int64) as current_inventory , g.order_quantity_of_month , sum(case when i.report_generated_date = m.opening_date then ifnull(cast(i.available_quantity as int64),0) else 0 end) as opening_inventory , sum(case when i.report_generated_date = m.closing_date then ifnull(cast(i.available_quantity as int64),0) else 0 end) as closing_inventory , sd.total_orders_in_month , sd.total_returns_in_month from sales_data sd left join inventory_details i on sd.sku = i.sku_code and sd.order_month = i.month left join month_start_and_end m on m.sku = sd.sku and m.month = sd.order_month left join sku_latest s on s.sku = sd.sku left join grn g on sd.sku = g.sku and sd.order_month = g.grn_completed_month group by 1,2,3,4,7,8; create or replace table maplemonk.ras_customer_lifetime as with inactive_customers_l6m as ( select maple_monk_id_phone as customer_id , email as customer_email , DATE_TRUNC(`Acquisition_D`, DAY) AS customer_acquisition_date , max(`Order_Date`) AS last_order_date from `MAPLEMONK.ras_sales_data` where date_diff(current_date(),Acquisition_D,day)>180 and channel like (\'%SHOPIFY%\') group by customer_id, email, customer_acquisition_date having date_diff(current_date(),max(order_timestamp),day)>180 ), total_customers_l6m as ( select maple_monk_id_phone as customer_id , email as customer_email , DATE_TRUNC(`Acquisition_D`, DAY) AS customer_acquisition_date , max(`Order_Date`) AS last_order_date , COUNT(*) as total_order_count_l6m from `MAPLEMONK.ras_sales_data` where date_diff(current_date(),acquisition_d,day)>180 and channel like (\'%SHOPIFY%\') group by maple_monk_id_phone, email, customer_acquisition_date ), churn_rate_l6m as ( select count(i.customer_id) as customer_id , count(t.customer_email) as customer_email , safe_divide(count(i.customer_id),count(t.customer_id)) as churn from total_customers_l6m t left join inactive_customers_l6m i on t.customer_id = i.customer_id ), inactive_customers_l12m as ( select maple_monk_id_phone as customer_id , email as customer_email , DATE_TRUNC(`Acquisition_D`, DAY) AS customer_acquisition_date , max(`Order_Date`) AS last_order_date from `MAPLEMONK.ras_sales_data` where date_diff(current_date(),Acquisition_D,day)>365 and channel like (\'%SHOPIFY%\') group by maple_monk_id_phone, email, customer_acquisition_date having date_diff(current_date(),max(order_timestamp),day)>365 ), total_customers_l12m as ( select maple_monk_id_phone as customer_id , email as customer_email , DATE_TRUNC(`Acquisition_D`, DAY) AS customer_acquisition_date_l12m , max(`Order_Date`) AS last_order_date , COUNT(*) as total_order_count_l12m from `MAPLEMONK.ras_sales_data` where date_diff(current_date(),acquisition_d,day)>365 and channel like (\'%SHOPIFY%\') group by maple_monk_id_phone, email, customer_acquisition_date_l12m ), churn_rate_l12m as ( select count(i12.customer_id) as inactive_customer_count_l12m , count(t12.customer_id) as total_customer_count_l12m , safe_divide(count(i12.customer_id),count(t12.customer_id)) as churn from total_customers_l12m t12 left join inactive_customers_l12m i12 on t12.customer_id = i12.customer_id ) select maple_monk_id_phone as customer_id , email as customer_email , name as Customer_name , acquisition_d , new_customer_flag as Customer_type , t6.total_order_count_l6m , t12.total_order_count_l12m , max(order_date) as last_order_date , sum(return_flag) as total_returns , (select c.churn from churn_rate_l6m c limit 1) as churn_rate_l6m , (select c.churn from churn_rate_l12m c limit 1) as churn_rate_l12m , safe_divide(sum(case when return_flag = 0 then selling_price else 0 end),sum(case when return_flag = 0 then 1 else 0 end)) as average_order_value , safe_divide(safe_divide(sum(case when return_flag = 0 then selling_price else 0 end),sum(case when return_flag = 0 then 1 else 0 end)),(select c.churn from churn_rate_l6m c limit 1)) as CLTV_l6m , safe_divide(safe_divide(sum(case when return_flag = 0 then selling_price else 0 end),sum(case when return_flag = 0 then 1 else 0 end)),(select c.churn from churn_rate_l12m c limit 1)) as CLTV_l12m from `MAPLEMONK.ras_sales_data` s left join total_customers_l12m t12 on cast(t12.customer_id as int64) = cast(s.maple_monk_id_phone as int64) left join total_customers_l6m t6 on cast(t6.customer_id as int64) = cast(s.maple_monk_id_phone as int64) where channel like (\'%SHOPIFY%\') and date_diff(current_date(),acquisition_d,day)>180 and total_order_count_l12m is null group by 1,2,3,4,5,6,7;",
                    "transaction": true
                }
            ) }}
